    if (fields[0] === "# base" && fields.length === 3 && !bases.has(fields[1])) bases.set(fields[1], fields[2]);
    else if (["format", "revision", "rules"].includes(key) && fields[0].startsWith("# ") && fields.length === 2 && !metadata.has(key)) metadata.set(key, fields[1]);
    else if (!fields[0].startsWith("#") && fields.length === 2 && !edits.has(fields[0])) edits.set(fields[0], fields[1]);
